			hexDump := fmt.Sprintf("%x", buf)
			return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w, partial data (hex): %s", err, hexDump)
		}
		return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w", err)
	}
	return http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
		// valid:    true,
	}, nil
}

