// StreamEndpoint is a function type for client-side streaming RPC endpoints.
// It handles the streaming communication with the server.
type StreamEndpoint func(ctx context.Context, args interface{}) (result interface{}, err error)

// StreamMiddleware is a function type for client-side streaming middleware.
type StreamMiddleware func(next StreamEndpoint) StreamEndpoint

// StreamMiddlewareBuilder builds a StreamMiddleware with information from a context.
type StreamMiddlewareBuilder func(ctx context.Context) StreamMiddleware

// StreamChain connects multiple streaming middlewares into a single middleware.
func StreamChain(mws ...StreamMiddleware) StreamMiddleware {
	return func(next StreamEndpoint) StreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

