package cep

import (
	"context"

	"github.com/cloudwego/kitex/pkg/endpoint"
)

// UnaryChain connects multiple unary middlewares into a single middleware.
func UnaryChain(mws ...endpoint.UnaryMiddleware) endpoint.UnaryMiddleware {
	return func(next endpoint.UnaryEndpoint) endpoint.UnaryEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// FromGenericEndpoint converts a generic endpoint.Endpoint to UnaryEndpoint.
func FromGenericEndpoint(ep endpoint.Endpoint) endpoint.UnaryEndpoint {
	return func(ctx context.Context, req, resp interface{}) error {
		return ep(ctx, req, resp)
	}
}

// ToGenericEndpoint converts a UnaryEndpoint to generic endpoint.Endpoint.
func ToGenericEndpoint(ep endpoint.UnaryEndpoint) endpoint.Endpoint {
	return func(ctx context.Context, req, resp interface{}) error {
		return ep(ctx, req, resp)
	}
}

