func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		// Enhanced error with hex dump for debugging
		if len(buf) > 0 && len(buf) >= 4 {
			first4Bytes := binary.BigEndian.Uint32(buf[:4])
			hexDump := fmt.Sprintf("%x", buf)
			return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w, first4Bytes=%#x, partial data (hex): %s", err, first4Bytes, hexDump)
		} else if len(buf) > 0 {
			hexDump := fmt.Sprintf("%x", buf)
			return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w, partial data (hex): %s", err, hexDump)
		}
		return http2.FrameHeader{}, fmt.Errorf("readFrameHeader error: %w", err)
	}
	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
		// valid:    true,
	}
	// Check frame size limit and return enhanced error if exceeded
	if fh.Length > fr.maxReadSize {
		return http2.FrameHeader{}, fmt.Errorf("%s or invalid frame (first4Bytes=%#x, second4Bytes=%#x)", http2.ErrFrameTooLarge, buf[:4], buf[4:8])
	}
	return fh, nil
}

